'use strict';
const coins=[{symbol:'SOL',name:'Solana',price:150,style:'sol',icon:'≋'},{symbol:'USDC',name:'USD Coin',price:1,style:'usdc',icon:'$'},{symbol:'BONK',name:'Bonk',price:.00002,style:'bonk',icon:'B'},{symbol:'WIF',name:'dogwifhat',price:1.2,style:'wif',icon:'W'},{symbol:'JUP',name:'Jupiter',price:.8,style:'jup',icon:'J'},{symbol:'PUMP',name:'Pump.fun',price:.004,style:'pump',icon:'P'}];
const $=id=>document.getElementById(id);let from=coins[0],to=coins[1],mode='swap',pace='High',pickSide='from',connected=false,recipientCount=1,reviewed=false;
const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:n<1?8:4}).format(n);const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:n>0&&n<.01?6:2}).format(n);const token=c=>`<span class="token ${c.style}">${c.icon}</span>`;
function amount(){const raw=$('amount').value.trim();return /^\d*\.?\d+$/.test(raw)?Number(raw):0}function output(){return amount()*from.price/to.price*.997}function setActive(selector,attr,val){document.querySelectorAll(selector).forEach(b=>{const active=b.dataset[attr]===val;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function render(){if(mode==='send')to=from;$('pickFrom').innerHTML=token(from)+from.symbol+' <span class="chevron">⌄</span>';$('pickTo').innerHTML=token(to)+to.symbol+' <span class="chevron">⌄</span>';$('pickTo').disabled=mode==='send';$('flip').disabled=mode==='send';const n=amount(),valid=Number.isFinite(n)&&n>0&&Number.isFinite(output());$('receive').textContent=valid?fmt(output()):'0.00';$('fromValue').textContent=valid?usd(n*from.price)+' · sample valuation':'Enter an amount to preview';$('route').textContent=mode==='send'?from.symbol+' transfer':from.symbol+' / '+to.symbol;$('review').disabled=!valid;$('review').textContent=valid?'Review demo '+mode:'Enter an amount';$('modeHint').textContent=mode==='swap'?'One coin in. Another coin out.':'Send the same coin to a new destination.';$('formError').textContent=''}
function showToast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('toast').hidden=true,3500)}
function pick(side){pickSide=side;$('coinSearch').value='';renderCoins();$('coinDialog').showModal();$('coinSearch').focus()}
function selectCoin(c){if(pickSide==='from'){from=c;if(mode==='swap'&&from===to)to=coins.find(x=>x!==from)}else{to=c;if(from===to)from=coins.find(x=>x!==to)}render();$('coinDialog').close()}
function renderCoins(){const query=$('coinSearch').value.toLowerCase();const matches=coins.filter(c=>(c.symbol+' '+c.name).toLowerCase().includes(query));$('coinList').replaceChildren();if(!matches.length){const p=document.createElement('p');p.textContent='No coins found. Try another name.';$('coinList').append(p)}matches.forEach(c=>{const b=document.createElement('button');b.className='coin-option';b.innerHTML=token(c)+`<div>${c.symbol}<small>${c.name}</small></div><span>${usd(c.price)}</span>`;b.onclick=()=>selectCoin(c);$('coinList').append(b)})}
$('amount').addEventListener('input',render);$('pickFrom').onclick=()=>pick('from');$('pickTo').onclick=()=>pick('to');$('coinSearch').oninput=renderCoins;$('flip').onclick=()=>{[from,to]=[to,from];render()};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;setActive('[data-mode]','mode',mode);if(mode==='swap'&&from===to)to=coins.find(c=>c!==from);render()});
document.querySelectorAll('[data-pace]').forEach(b=>b.onclick=()=>{pace=b.dataset.pace;setActive('[data-pace]','pace',pace)});
$('addRecipient').onclick=()=>{if($('recipients').children.length>=5)return;recipientCount++;const row=document.createElement('div');row.className='recipient-row';const input=document.createElement('input');input.placeholder='Another Solana wallet address';input.setAttribute('aria-label','Recipient wallet '+recipientCount);input.autocomplete='off';input.spellcheck=false;const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove recipient '+recipientCount);remove.onclick=()=>{row.remove();$('addRecipient').disabled=false;render()};row.append(input,remove);$('recipients').append(row);$('addRecipient').disabled=$('recipients').children.length>=5;input.focus()};
$('connect').onclick=()=>{if(connected){connected=false;$('connect').textContent='Connect wallet';showToast('Demo wallet disconnected')}else $('walletDialog').showModal()};$('demoConnect').onclick=()=>{connected=true;$('connect').textContent='Demo wallet';$('walletDialog').close();showToast('Demo wallet connected · no real funds')};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
const steps=[['01 / CHOOSE','Start with what you have.','Pick the coin you want to send, enter an amount, and choose what you want to receive. Everything in one simple flow.','Many possibilities. One clear path.'],['02 / AGGREGATE','Bring the details together.','Set your destination and preferred pace. See the estimated output and sample fee before you continue.','Every detail, in one place.'],['03 / ARRIVE','See the whole picture.','Review the destination and estimated amount, then complete the simulation. Your real coins stay exactly where they are.','Your next move starts with clarity.']];
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.step),s=steps[i];setActive('[data-step]','step',String(i));$('stepNumber').textContent=s[0];$('stepTitle').textContent=s[1];$('stepCopy').textContent=s[2];$('flowCaption').textContent=s[3]});
coins.forEach(c=>{const b=document.createElement('button');b.className='coin-card';b.innerHTML=token(c)+`<span><b>${c.symbol}</b><small>${c.name}</small></span><span class="coin-action">Try swap</span>`;b.setAttribute('aria-label','Try swapping '+c.name);b.onclick=()=>{mode='swap';setActive('[data-mode]','mode',mode);from=c;if(from===to)to=coins.find(x=>x!==from);render();$('swap').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('amount').focus({preventScroll:true})};$('coinGrid').append(b)});
const addressValid=s=>{if(!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(s))return false;const alphabet='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';let n=0n;for(const ch of s)n=n*58n+BigInt(alphabet.indexOf(ch));let bytes=0;while(n>0n){bytes++;n>>=8n}return bytes+(s.match(/^1*/)[0].length)===32};
$('review').onclick=()=>{const addresses=[...$('recipients').querySelectorAll('input')].map(i=>i.value.trim());if(addresses.some(a=>a&&!addressValid(a))){$('formError').textContent='Enter a valid Solana address, or leave the destination empty to use a demo wallet.';return}reviewed=false;$('reviewTitle').textContent='Review demo '+mode;$('completeDemo').textContent='Complete demo';$('reviewContent').replaceChildren();const amountBlock=document.createElement('div');amountBlock.className='review-amount';amountBlock.textContent=fmt(amount())+' '+from.symbol;const receive=document.createElement('span');receive.textContent='Receive ≈ '+fmt(output())+' '+to.symbol;amountBlock.append(receive);$('reviewContent').append(amountBlock);const dl=document.createElement('dl');dl.className='pairs';const rows=[['Pace',pace],['Sample fee',fmt(amount()*.003)+' '+from.symbol],['Recipients',String(addresses.length)],['Per recipient',fmt(output()/addresses.length)+' '+to.symbol],...addresses.map((a,i)=>['Destination '+(i+1),a||'Demo recipient '+(i+1)])];rows.forEach(([k,v])=>{const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;row.append(dt,dd);dl.append(row)});$('reviewContent').append(dl);$('reviewDialog').showModal()};
$('completeDemo').onclick=()=>{if(reviewed){$('reviewDialog').close();return}reviewed=true;$('reviewTitle').textContent='Demo complete';$('reviewContent').innerHTML='<div class="success"><span class="check">✓</span><h3>Your next move, previewed.</h3><p>You completed the Aggregate demo. No funds were sent and no transaction was created.</p></div>';$('completeDemo').textContent='Back to Aggregate'};
render();
